@media (max-width: 768px) {
  .login-page { grid-template-columns: 1fr; }
  .login-brand { display: none; }
  .login-form-panel { padding: 32px 24px; }
}
</style>
</head>
<body>
<div class="login-page">

  <!-- BRAND PANEL -->
  <div class="login-brand">
    <div class="login-brand-content">
      <div class="login-brand-logo">CreativeHub</div>
      <h2 class="brand-tagline">Find inspiration and showcase your creative work.</h2>
      <div class="brand-features">
        <div class="brand-feature">
          <div class="brand-feature-icon"><i class="ri-play-circle-line"></i></div>
          <div class="brand-feature-text"><strong>+1,000 free courses</strong> — illustration, photography, design, crafts, and more.</div>
        </div>
        <div class="brand-feature">
          <div class="brand-feature-icon"><i class="ri-group-line"></i></div>
          <div class="brand-feature-text"><strong>Global community</strong> — share projects, get feedback, connect with creatives worldwide.</div>
        </div>
        <div class="brand-feature">
          <div class="brand-feature-icon"><i class="ri-medal-line"></i></div>
          <div class="brand-feature-text"><strong>Earn certificates</strong> — personalized, signed by your teacher, shareable on LinkedIn.</div>
        </div>
        <div class="brand-feature">
          <div class="brand-feature-icon"><i class="ri-time-line"></i></div>
          <div class="brand-feature-text"><strong>Learn at your pace</strong> — unlimited access, watch anytime, from any device.</div>
        </div>
      </div>
    </div>
  </div>

  <!-- FORM PANEL -->
  <div class="login-form-panel">
    <div class="login-card">
      <h1 class="login-title">Log in.</h1>
      <p class="login-subtitle">Find inspiration and showcase your creative work.</p>

      <div class="social-btns">
        <button class="social-btn facebook" onclick="handleSocialLogin('Facebook')">
          <i class="ri-facebook-fill"></i> Log in with Facebook
        </button>
        <button class="social-btn apple" onclick="handleSocialLogin('Apple')">
          <i class="ri-apple-fill"></i> Sign in with Apple
        </button>
      </div>

      <div class="divider"><span>or log in with email</span></div>

      <form id="loginForm" onsubmit="handleLogin(event)" novalidate>
        <div class="form-group">
          <label class="form-label" for="email">Email address</label>
          <input class="form-input" type="email" id="email" name="email"
            placeholder="you@example.com" autocomplete="email" required>
          <div class="form-error" id="emailError">Please enter a valid email address.</div>
        </div>

        <div class="form-group">
          <label class="form-label" for="password">Password</label>
          <div class="input-wrap">
            <input class="form-input" type="password" id="password" name="password"
              placeholder="Your password" autocomplete="current-password" required>
            <button type="button" class="eye-btn" id="eyeBtn" onclick="togglePassword()" aria-label="Toggle password visibility">
              <i class="ri-eye-off-line" id="eyeIcon"></i>
            </button>
          </div>
          <div class="form-error" id="passwordError">Please enter your password.</div>
          <div class="forgot-row">
            <a href="#" class="forgot-link">Forgot your password?</a>
          </div>
        </div>

        <button type="submit" class="btn-login" id="loginBtn">
          <span id="loginBtnText">Log in</span>
          <i class="ri-arrow-right-line"></i>
        </button>
      </form>

      <div class="join-row">
        Don't have an account? <a href="plus.html">Join for Free</a>
      </div>

    </div>
  </div>

</div><!-- /login-page -->

<script>
function togglePassword() {
  const input = document.getElementById('password');
  const icon = document.getElementById('eyeIcon');
  if (input.type === 'password') {
    input.type = 'text';
    icon.className = 'ri-eye-line';
  } else {
    input.type = 'password';
    icon.className = 'ri-eye-off-line';
  }
}

function handleLogin(e) {
  e.preventDefault();
  const email = document.getElementById('email').value.trim();
  const password = document.getElementById('password').value;
  const emailErr = document.getElementById('emailError');
  const passErr = document.getElementById('passwordError');
  let valid = true;

  // Reset errors
  emailErr.style.display = 'none';
  passErr.style.display = 'none';
  document.getElementById('email').style.borderColor = '';
  document.getElementById('password').style.borderColor = '';

  // Validate email
  const emailRe = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!email || !emailRe.test(email)) {
    emailErr.style.display = 'block';
    document.getElementById('email').style.borderColor = 'var(--primary)';
    valid = false;
  }

  // Validate password
  if (!password) {
    passErr.style.display = 'block';
    document.getElementById('password').style.borderColor = 'var(--primary)';
    valid = false;
  }

  if (!valid) return;

  // Simulate form submission
  const btn = document.getElementById('loginBtn');
  const btnText = document.getElementById('loginBtnText');
  btn.disabled = true;
  btnText.textContent = 'Logging in…';

  setTimeout(() => {
    btn.disabled = false;
    btnText.textContent = 'Log in';
    // In production, this would redirect or handle auth
    alert('Login submitted! (Demo mode — no backend connected)');
  }, 1200);
}

function handleSocialLogin(provider) {
  alert(`${provider} login initiated. (Demo mode — no backend connected)`);
}
</script>
</body>
</html>
